#include <Arduino.h>
#include <Wire.h>
#include <Adafruit_MPU6050.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_TMP117.h>
#include "MAX30100_PulseOximeter.h"

#include "config.h"
#include "ble_service.h"

// -------------------------------------------------------------
